{
  "iteration": 2,
  "pcvs": [
    {
      "name": "batch_size",
      "expression": "len(output_token_ids)",
      "rationale": "Captures per-row conversion and penalty setup."
    },
    {
      "name": "logit_elements",
      "expression": "logits.numel()",
      "rationale": "Captures dense vocabulary-wide penalty work."
    },
    {
      "name": "prompt_elements",
      "expression": "prompt_token_ids.numel()",
      "rationale": "Captures prompt-token scatter work."
    },
    {
      "name": "singleton_batch",
      "expression": "int(len(output_token_ids) == 1)",
      "rationale": "Separates the singleton entry state, which exhibited substantially higher instruction count than the remaining batches."
    }
  ],
  "hypothesis": "A singleton-state indicator captures the observed cost discontinuity, while batch size and tensor cardinalities explain the remaining scaling. The current measurements cannot distinguish singleton-specific overhead from first-call initialization."
}
